export function menuBoardSVG(){return `<svg xmlns="http://www.w3.org/2000/svg" width="2048" height="672" viewBox="0 0 2048 672"><rect width="2048" height="672" rx="18" fill="#f4eddd"/><rect x="14" y="14" width="2020" height="644" rx="12" fill="none" stroke="#bca06d" stroke-width="2"/><path d="M0 0H2048V139H0Z" fill="#183f37"/><text x="64" y="91" fill="#fbf1db" font-size="74" font-family="Georgia,serif">De Caro Coffee Club</text><text x="1983" y="69" text-anchor="end" fill="#d4c49d" font-size="22" letter-spacing="5" font-family="Arial,sans-serif">IL RISTOBAR SUL GOLFO</text><text x="1983" y="106" text-anchor="end" fill="#eee3c8" font-size="21" font-family="Arial,sans-serif">Una pausa. Nuove idee.</text>${cafeMenu.map((category,i)=>{const x=64+i*672;return `<g transform="translate(${x} 0)">${i?'<path d="M-32 181V570" stroke="#d0c1a4" stroke-width="2"/>':''}<text x="0" y="212" fill="#1e4a3e" font-size="43" font-family="Georgia,serif">${text(category.title)}</text><text x="0" y="252" fill="#8c795c" font-size="21" font-family="Arial,sans-serif">${category.subtitle}</text>${category.items.map(([name],j)=>`<text x="0" y="${330+j*86}" fill="#29473e" font-size="32" font-family="Arial,sans-serif">${text(name)}</text><path d="M0 ${348+j*86}H300" stroke="#d9cfb9"/>`).join('')}<g transform="translate(350 285) scale(.98)">${illustration(category.kind)}</g></g>`;}).join('')}<path d="M64 598H1984" stroke="#c8b48c"/><text x="64" y="640" fill="#7d6d53" font-size="20" letter-spacing="4" font-family="Arial,sans-serif">CAFFÈ · CONVERSAZIONI · VISTA NAPOLI</text><text x="1984" y="640" text-anchor="end" fill="#7d6d53" font-size="20" font-family="Arial,sans-serif">Accomodati, sei in Studio De Caro.</text></svg>`;}
